FQN: Example: Read the size of a one-pixel BMP file
Kind: verified_example
Provenance: authored
Verification: passed
Authored example: written for foss-mcp against the pinned library, not taken from the upstream README; published only after the ingestion verifier compiled or ran it against that commit.
Builds a one-pixel 24-bit BMP in memory, writes it to a temporary file, reads its width, height and bit depth with ImageProbe.ProbeFile and then deletes the file.

Example:
// Authored example: read the size of a BMP file with ProbeFile
using System;
using System.IO;
using Aspose.Imaging.Foss;

byte[] bmp =
{
    // File header: "BM", file size (58), reserved, pixel data offset (54).
    0x42, 0x4D, 0x3A, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x36, 0x00, 0x00, 0x00,
    // Info header: size (40), width (1), height (1), planes (1), bits per pixel (24).
    0x28, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00, 0x18, 0x00,
    // Compression, image size (4), resolution and palette fields.
    0x00, 0x00, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    // One blue-green-red pixel plus one byte of row padding.
    0xFF, 0x00, 0x00, 0x00,
};

string path = Path.Combine(Path.GetTempPath(), "one-pixel-sample.bmp");
File.WriteAllBytes(path, bmp);
try
{
    ImageInfo info = ImageProbe.ProbeFile(path);
    Console.WriteLine($"{info.Format}: {info.Width}x{info.Height}, {info.BitDepth}-bit");
}
finally
{
    File.Delete(path);
}
